+ (BOOL)readOnlyTool:(NSDictionary *)tool{
 NSDictionary *a=[tool[@"annotations"] isKindOfClass:NSDictionary.class]?tool[@"annotations"]:@{};
 if(![a[@"readOnlyHint"] isEqual:@YES]||(a[@"destructiveHint"]&&![a[@"destructiveHint"] isEqual:@NO]))return NO;
